import * as React from "react"
import { Link, HeadFC, PageProps, graphql } from "gatsby"
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import Layout from "../components/layout"

const userData: UserProfile = data;

const NotFoundPage: React.FC<PageProps> = () => {
  return (
    <Layout data={userData}>
      <section className={styles.container}>
        <article className={styles.section}>
          <div className=" h-96">
            <h1 className={styles.title}>Page not found</h1>
            <h2 className={styles.subtitle}>{userData.name}</h2>            
          </div>
        </article>
      </section>
    </Layout>
  )
}

export default NotFoundPage

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "flex flex-col w-full p-8 gap-8 text-2xl",
  section: "flex-col flex bg-primary/50 border-primary flex p-8  border rounded-lg shadow-lg shadow-neutral/50",
  title: "text-accent text-5xl ",
  subtitle: "text-neutral text-4xl",
  paragraph : "text-neutral-700 my-5",
  button: " text-accent hover:text-neutral bg-primary hover:bg-accent px-8 py-2 text-xl shadow-xl shadow-warning-500 rounded-lg",
  articleWrapper: "flex flex-col sm:flex-row grow min-h-full h-full"
}